// ============================================================
// UpsampleNearest3dGrad Host — 预计算最近邻索引映射 + Tiling + Kernel Launch
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_upsample_nearest_3d_grad.h"
#include <torch/extension.h>
#include <algorithm>
#include <vector>

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTES = 512;
constexpr int64_t UB_ALIGN_BYTES = 32;
// indexBuf 为 int32, 按 32B 对齐: 32 / 4 = 8 个元素对齐
constexpr int64_t INDEX_ALIGN_ELEMS = 8;

at::Tensor upsample_nearest_3d_grad(
    const at::Tensor& grad_output,
    const at::IntArrayRef& output_size,
    const at::IntArrayRef& input_size,
    double scales_d,
    double scales_h,
    double scales_w) {

    // ---- 输入校验 ----
    TORCH_CHECK(grad_output.device().type() == at::DeviceType::PrivateUse1,
                "upsample_nearest_3d_grad: grad_output must be on NPU device");
    TORCH_CHECK(grad_output.dim() == 5,
                "upsample_nearest_3d_grad: grad_output must be 5D (N,C,D,H,W)");
    TORCH_CHECK(grad_output.scalar_type() == at::kFloat ||
                grad_output.scalar_type() == at::kHalf ||
                grad_output.scalar_type() == at::kBFloat16,
                "upsample_nearest_3d_grad: only float32, float16 and bfloat16 are supported");

    // ---- 参数提取 ----
    int64_t N = output_size[0];
    int64_t C = output_size[1];
    int64_t oD = output_size[2];
    int64_t oH = output_size[3];
    int64_t oW = output_size[4];
    int64_t iD = input_size[2];
    int64_t iH = input_size[3];
    int64_t iW = input_size[4];

    int64_t ospatSize = oD * oH * oW;
    int64_t ispatSize = iD * iH * iW;
    int64_t totalLength = N * C * ospatSize;

    int64_t dtypeSize = grad_output.element_size();

    // ---- 连续化 ----
    auto gradOutputContiguous = grad_output.contiguous();

    // ---- 预计算最近邻索引映射 (CPU) ----
    float scale_d = (iD > 0) ? (float)iD / (float)oD : 1.0f;
    float scale_h = (iH > 0) ? (float)iH / (float)oH : 1.0f;
    float scale_w = (iW > 0) ? (float)iW / (float)oW : 1.0f;

    std::vector<int32_t> mappedIndices(ospatSize);
    for (int64_t od = 0; od < oD; ++od) {
        int64_t id = (int64_t)((float)od * scale_d);
        if (id < 0) id = 0;
        if (id >= iD) id = iD - 1;
        for (int64_t oh = 0; oh < oH; ++oh) {
            int64_t ih = (int64_t)((float)oh * scale_h);
            if (ih < 0) ih = 0;
            if (ih >= iH) ih = iH - 1;
            for (int64_t ow = 0; ow < oW; ++ow) {
                int64_t iw = (int64_t)((float)ow * scale_w);
                if (iw < 0) iw = 0;
                if (iw >= iW) iw = iW - 1;
                int64_t ospat = od * oH * oW + oh * oW + ow;
                int64_t ispat = id * iH * iW + ih * iW + iw;
                mappedIndices[ospat] = static_cast<int32_t>(ispat);
            }
        }
    }

    // 创建 mapped_indices tensor on NPU
    auto mappedIndicesCpu = at::from_blob(
        mappedIndices.data(), {ospatSize},
        at::TensorOptions().dtype(at::kInt).device(at::kCPU));
    auto mappedIndicesContiguous = mappedIndicesCpu.to(grad_output.device()).contiguous();

    // ---- 创建输出 tensor (预初始化 zero) ----
    auto gradInput = at::zeros({N, C, iD, iH, iW},
        grad_output.options().dtype(grad_output.scalar_type()));
    auto gradInputContiguous = gradInput.contiguous();
    auto gradInputFlat = gradInputContiguous.view({-1});

    // ---- Platform Setup ----
    auto platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(platform->GetCoreNumAiv());
    uint64_t ubSize;
    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // ---- Block 级 Tiling (核间切分) ----
    // Cache Line 对齐
    int64_t alignElements512 = CACHE_LINE_BYTES / dtypeSize;
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign =
        ((totalLengthCore + alignElements512 - 1) / alignElements512) * alignElements512;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int64_t formerNum = usedCoreNum - 1;
    int64_t tailNum = 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - (usedCoreNum - 1) * formerLength;
    if (tailLength < 0) tailLength = 0;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // ---- UB 级 Tiling (核内切分) ----
    // 索引 buffer: ospat 最大约 32768, 对应 128KB
    // 整数对齐 indexBatchSize
    int64_t indexBatchSizeUnaligned = ospatSize;
    int64_t indexBatchBytes = indexBatchSizeUnaligned * sizeof(int32_t);
    // 限制索引 buffer 不超过 UB 的 60% (留 40% 给 grad data)
    int64_t maxIndexBytes = static_cast<int64_t>(ubSize) * 6 / 10;
    while (indexBatchBytes > maxIndexBytes && indexBatchSizeUnaligned > 0) {
        indexBatchSizeUnaligned /= 2;
        indexBatchBytes = indexBatchSizeUnaligned * sizeof(int32_t);
    }
    // 32B 对齐 indexBatchSize (int32: 8 elements per 32B)
    int64_t indexBatchSize = (indexBatchSizeUnaligned / INDEX_ALIGN_ELEMS) * INDEX_ALIGN_ELEMS;
    if (indexBatchSize < INDEX_ALIGN_ELEMS) indexBatchSize = INDEX_ALIGN_ELEMS;

    // 剩余 UB 用于 grad data double buffer
    int64_t ubRemainingBytes = static_cast<int64_t>(ubSize) - indexBatchSize * sizeof(int32_t);
    int64_t maxTileElements = ubRemainingBytes / (dtypeSize * 2);  // BUFFER_NUM = 2
    int64_t alignElements32 = UB_ALIGN_BYTES / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements32) * alignElements32;
    if (tileLength < alignElements32) tileLength = alignElements32;

    // ---- EXEC_KERNEL_CMD (所有参数必须为左值) ----
    EXEC_KERNEL_CMD(upsample_nearest_3d_grad, blockDim,
                    gradOutputContiguous, gradInputFlat, mappedIndicesContiguous,
                    totalLength, formerNum, formerLength,
                    tailNum, tailLength, tileLength,
                    ospatSize, ispatSize, indexBatchSize,
                    dtypeSize);

    return gradInput;
}

}  // namespace ascend_kernel
