148	
149	template<typename T>
150	__aicore__ inline void UpsampleNearest3dGradKernel<T>::CopyIn(
151	    int64_t progress, int64_t curTileLength) {
152	
153	    int64_t globalOffset = coreStart_ + progress * tileLength_;
154	    LocalTensor<T> gradLocal = gradQueue.AllocTensor<T>();
155	
156	    DataCopyExtParams copyParams;
157	    copyParams.blockCount = 1;
158	    copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(T));
159	    DataCopyPad(gradLocal, gradOutputGm[globalOffset], copyParams);
160	
161	    gradQueue.EnQue(gradLocal);
162	}
163	
164	// =========================== Compute ============================
165	
166	template<typename T>
167	__aicore__ inline void UpsampleNearest3dGradKernel<T>::Compute(
168	    int64_t progress, int64_t curTileLength) {
169	
170	    LocalTensor<T> gradLocal = gradQueue.DeQue<T>();
171	    LocalTensor<int32_t> indexLocal = indexBuf.Get<int32_t>();
172	
173	    int64_t globalStart = coreStart_ + progress * tileLength_;
174	    int64_t batchIdx = globalStart / ospatSize_;
175	    int64_t ospat = globalStart - batchIdx * ospatSize_;
176	
177	    for (int64_t i = 0; i < curTileLength; ++i) {
178	        int32_t targetSpat = indexLocal.GetValue(ospat);
179	        int64_t targetGlobal = batchIdx * ispatSize_ + targetSpat;
180	
181	        SetAtomicAdd<T>();
182	        DataCopyExtParams copyParams;
183	        copyParams.blockCount = 1;
184	        copyParams.blockLen = static_cast<uint32_t>(sizeof(T));
185	        DataCopyPad(gradInputGm[targetGlobal], gradLocal[i], copyParams);
186	        SetAtomicNone();
187	
188	        ospat++;
189	        if (ospat == ospatSize_) {
190	            ospat = 0;
191	            batchIdx++;
192	        }
193	    }
194	
195	    gradQueue.FreeTensor(gradLocal);
196	}
197	
198	// =========================== Kernel Entry ============================
199	// fp16 和 bf16 均为 2 字节搬运类操作，统一走 half 路径
200	
201	extern "C" __global__ __aicore__ void upsample_nearest_3d_grad(
202	    GM_ADDR gradOutput, GM_ADDR gradInput, GM_ADDR mappedIndices,
203	    int64_t totalLength, int64_t formerNum, int64_t formerLength,
204	    int64_t tailNum, int64_t tailLength, int64_t tileLength,
205	    int64_t ospatSize, int64_t ispatSize, int64_t indexBatchSize,
206	    int64_t dtypeSize) {
207	
208	    if (dtypeSize == 4) {
209	        UpsampleNearest3dGradKernel<float> op;
210	        op.Init(gradOutput, gradInput, mappedIndices,
211	                totalLength, formerNum, formerLength,
212	                tailNum, tailLength, tileLength,
213	                ospatSize, ispatSize, indexBatchSize);
214	        op.Process();
215	    } else if (dtypeSize == 2) {
216	        UpsampleNearest3dGradKernel<half> op;
217	        op.Init(gradOutput, gradInput, mappedIndices,
218	                totalLength, formerNum, formerLength,
219	                tailNum, tailLength, tileLength,
220	                ospatSize, ispatSize, indexBatchSize);
221	        op.Process();
222	    }
223	}
