10	
11	// ============================================================
12	// UpsampleNearest3dGrad Host — 预计算最近邻索引映射 + Tiling + Kernel Launch
13	// ============================================================
14	
15	#include "torch_kernel_helper.h"
16	#include "tiling/platform/platform_ascendc.h"
17	#include "aclrtlaunch_upsample_nearest_3d_grad.h"
18	#include <torch/extension.h>
19	#include <algorithm>
20	#include <vector>
21	
22	namespace ascend_kernel {
23	
24	constexpr int64_t CACHE_LINE_BYTES = 512;
25	constexpr int64_t UB_ALIGN_BYTES = 32;
26	// indexBuf 为 int32, 按 32B 对齐: 32 / 4 = 8 个元素对齐
27	constexpr int64_t INDEX_ALIGN_ELEMS = 8;
28	
29	at::Tensor upsample_nearest_3d_grad(
30	    const at::Tensor& grad_output,
31	    const at::IntArrayRef& output_size,
32	    const at::IntArrayRef& input_size,
33	    double scales_d,
34	    double scales_h,
35	    double scales_w) {
36	
37	    // ---- 输入校验 ----
38	    TORCH_CHECK(grad_output.device().type() == at::DeviceType::PrivateUse1,
39	                "upsample_nearest_3d_grad: grad_output must be on NPU device");
40	    TORCH_CHECK(grad_output.dim() == 5,
41	                "upsample_nearest_3d_grad: grad_output must be 5D (N,C,D,H,W)");
42	    TORCH_CHECK(grad_output.scalar_type() == at::kFloat ||
43	                grad_output.scalar_type() == at::kHalf ||
44	                grad_output.scalar_type() == at::kBFloat16,
45	                "upsample_nearest_3d_grad: only float32, float16 and bfloat16 are supported");
46	
47	    // ---- 参数提取 ----
48	    int64_t N = output_size[0];
49	    int64_t C = output_size[1];
50	    int64_t oD = output_size[2];
51	    int64_t oH = output_size[3];
52	    int64_t oW = output_size[4];
53	    int64_t iD = input_size[2];
54	    int64_t iH = input_size[3];
55	    int64_t iW = input_size[4];
56	
57	    int64_t ospatSize = oD * oH * oW;
58	    int64_t ispatSize = iD * iH * iW;
59	    int64_t totalLength = N * C * ospatSize;
60	
61	    int64_t dtypeSize = grad_output.element_size();
62	
63	    // ---- 连续化 ----
64	    auto gradOutputContiguous = grad_output.contiguous();
65	
66	    // ---- 预计算最近邻索引映射 (CPU) ----
67	    float scale_d = (iD > 0) ? (float)iD / (float)oD : 1.0f;
68	    float scale_h = (iH > 0) ? (float)iH / (float)oH : 1.0f;
69	    float scale_w = (iW > 0) ? (float)iW / (float)oW : 1.0f;
70	
71	    std::vector<int32_t> mappedIndices(ospatSize);
72	    for (int64_t od = 0; od < oD; ++od) {
73	        int64_t id = (int64_t)((float)od * scale_d);
74	        if (id < 0) id = 0;
75	        if (id >= iD) id = iD - 1;
76	        for (int64_t oh = 0; oh < oH; ++oh) {
77	            int64_t ih = (int64_t)((float)oh * scale_h);
78	            if (ih < 0) ih = 0;
79	            if (ih >= iH) ih = iH - 1;
80	            for (int64_t ow = 0; ow < oW; ++ow) {
81	                int64_t iw = (int64_t)((float)ow * scale_w);
82	                if (iw < 0) iw = 0;
83	                if (iw >= iW) iw = iW - 1;
84	                int64_t ospat = od * oH * oW + oh * oW + ow;
85	                int64_t ispat = id * iH * iW + ih * iW + iw;
86	                mappedIndices[ospat] = static_cast<int32_t>(ispat);
87	            }
88	        }
89	    }
90	
91	    // 创建 mapped_indices tensor on NPU
92	    auto mappedIndicesCpu = at::from_blob(
93	        mappedIndices.data(), {ospatSize},
94	        at::TensorOptions().dtype(at::kInt).device(at::kCPU));
95	    auto mappedIndicesContiguous = mappedIndicesCpu.to(grad_output.device()).contiguous();
96	
97	    // ---- 创建输出 tensor (预初始化 zero) ----
98	    auto gradInput = at::zeros({N, C, iD, iH, iW},
99	        grad_output.options().dtype(grad_output.scalar_type()));
100	    auto gradInputContiguous = gradInput.contiguous();
101	    auto gradInputFlat = gradInputContiguous.view({-1});
102	
103	    // ---- Platform Setup ----
104	    auto platform = platform_ascendc::PlatformAscendCManager::GetInstance();
105	    int64_t coreNum = static_cast<int64_t>(platform->GetCoreNumAiv());
106	    uint64_t ubSize;
107	    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
108	
109	    // ---- Block 级 Tiling (核间切分) ----
110	    // Cache Line 对齐
111	    int64_t alignElements512 = CACHE_LINE_BYTES / dtypeSize;
112	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
113	    int64_t totalLengthCoreAlign =
114	        ((totalLengthCore + alignElements512 - 1) / alignElements512) * alignElements512;
115	
116	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
117	    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
118	    if (usedCoreNum < 1) usedCoreNum = 1;
119	
120	    int64_t formerNum = usedCoreNum - 1;
121	    int64_t tailNum = 1;
122	    int64_t formerLength = totalLengthCoreAlign;
123	    int64_t tailLength = totalLength - (usedCoreNum - 1) * formerLength;
124	    if (tailLength < 0) tailLength = 0;
125	
126	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
127	
128	    // ---- UB 级 Tiling (核内切分) ----
129	    // 索引 buffer: ospat 最大约 32768, 对应 128KB
130	    // 整数对齐 indexBatchSize
131	    int64_t indexBatchSizeUnaligned = ospatSize;
132	    int64_t indexBatchBytes = indexBatchSizeUnaligned * sizeof(int32_t);
133	    // 限制索引 buffer 不超过 UB 的 60% (留 40% 给 grad data)
134	    int64_t maxIndexBytes = static_cast<int64_t>(ubSize) * 6 / 10;
135	    while (indexBatchBytes > maxIndexBytes && indexBatchSizeUnaligned > 0) {
136	        indexBatchSizeUnaligned /= 2;
137	        indexBatchBytes = indexBatchSizeUnaligned * sizeof(int32_t);
138	    }
139	    // 32B 对齐 indexBatchSize (int32: 8 elements per 32B)
140	    int64_t indexBatchSize = (indexBatchSizeUnaligned / INDEX_ALIGN_ELEMS) * INDEX_ALIGN_ELEMS;
141	    if (indexBatchSize < INDEX_ALIGN_ELEMS) indexBatchSize = INDEX_ALIGN_ELEMS;
142	
143	    // 剩余 UB 用于 grad data double buffer
144	    int64_t ubRemainingBytes = static_cast<int64_t>(ubSize) - indexBatchSize * sizeof(int32_t);
145	    int64_t maxTileElements = ubRemainingBytes / (dtypeSize * 2);  // BUFFER_NUM = 2
146	    int64_t alignElements32 = UB_ALIGN_BYTES / dtypeSize;
147	    int64_t tileLength = (maxTileElements / alignElements32) * alignElements32;
148	    if (tileLength < alignElements32) tileLength = alignElements32;
149	
150	    // ---- EXEC_KERNEL_CMD (所有参数必须为左值) ----
151	    EXEC_KERNEL_CMD(upsample_nearest_3d_grad, blockDim,
152	                    gradOutputContiguous, gradInputFlat, mappedIndicesContiguous,
153	                    totalLength, formerNum, formerLength,
154	                    tailNum, tailLength, tileLength,
155	                    ospatSize, ispatSize, indexBatchSize,
156	                    dtypeSize);
157	
158	    return gradInput;
159	}
160	
161	}  // namespace ascend_kernel
