29	at::Tensor upsample_nearest_3d_grad(
30	    const at::Tensor& grad_output,
31	    const at::IntArrayRef& output_size,
32	    const at::IntArrayRef& input_size,
33	    double scales_d,
34	    double scales_h,
35	    double scales_w) {
36	
37	    // ---- 输入校验 ----
38	    TORCH_CHECK(grad_output.device().type() == at::DeviceType::PrivateUse1,
39	                "upsample_nearest_3d_grad: grad_output must be on NPU device");
40	    TORCH_CHECK(grad_output.dim() == 5,
41	                "upsample_nearest_3d_grad: grad_output must be 5D (N,C,D,H,W)");
42	    TORCH_CHECK(grad_output.scalar_type() == at::kFloat ||
43	                grad_output.scalar_type() == at::kHalf ||
44	                grad_output.scalar_type() == at::kBFloat16,
45	                "upsample_nearest_3d_grad: only float32, float16 and bfloat16 are supported");
46	
47	    // ---- 参数提取 ----
48	    int64_t N = output_size[0];
49	    int64_t C = output_size[1];
50	    int64_t oD = output_size[2];
51	    int64_t oH = output_size[3];
52	    int64_t oW = output_size[4];
53	    int64_t iD = input_size[2];
54	    int64_t iH = input_size[3];
55	    int64_t iW = input_size[4];
56	
57	    int64_t ospatSize = oD * oH * oW;
58	    int64_t ispatSize = iD * iH * iW;
59	    int64_t totalLength = N * C * ospatSize;
60	
61	    // 参考实现始终在 float32 下累加。Host 只处理 float32 输入，
62	    // dtype 转换由 model_new_ascendc.py 完成。
63	    int64_t dtypeSize = grad_output.element_size();
64	
65	    // ---- 连续化 ----
66	    auto gradOutputContiguous = grad_output.contiguous();
67	
68	    // ---- 预计算最近邻索引映射 (CPU) ----
69	    float scale_d = (iD > 0) ? (float)iD / (float)oD : 1.0f;
70	    float scale_h = (iH > 0) ? (float)iH / (float)oH : 1.0f;
71	    float scale_w = (iW > 0) ? (float)iW / (float)oW : 1.0f;
72	
73	    std::vector<int32_t> mappedIndices(ospatSize);
74	    for (int64_t od = 0; od < oD; ++od) {
75	        int64_t id = (int64_t)((float)od * scale_d);
76	        if (id < 0) id = 0;
77	        if (id >= iD) id = iD - 1;
78	        for (int64_t oh = 0; oh < oH; ++oh) {
79	            int64_t ih = (int64_t)((float)oh * scale_h);
80	            if (ih < 0) ih = 0;
81	            if (ih >= iH) ih = iH - 1;
82	            for (int64_t ow = 0; ow < oW; ++ow) {
83	                int64_t iw = (int64_t)((float)ow * scale_w);
84	                if (iw < 0) iw = 0;
85	                if (iw >= iW) iw = iW - 1;
86	                int64_t ospat = od * oH * oW + oh * oW + ow;
87	                int64_t ispat = id * iH * iW + ih * iW + iw;
88	                mappedIndices[ospat] = static_cast<int32_t>(ispat);
89	            }
90	        }
91	    }
92	
93	    // 创建 mapped_indices tensor on NPU
94	    auto mappedIndicesCpu = at::from_blob(
95	        mappedIndices.data(), {ospatSize},
96	        at::TensorOptions().dtype(at::kInt).device(at::kCPU));
97	    auto mappedIndicesContiguous = mappedIndicesCpu.to(grad_output.device()).contiguous();
98	
99	    // ---- 创建输出 tensor ----
100	    auto gradInput = at::zeros({N, C, iD, iH, iW},
101	        grad_output.options());
102	    auto gradInputContiguous = gradInput.contiguous();
103	    auto gradInputFlat = gradInputContiguous.view({-1});
104	
105	    // ---- Platform Setup ----
106	    auto platform = platform_ascendc::PlatformAscendCManager::GetInstance();
107	    int64_t coreNum = static_cast<int64_t>(platform->GetCoreNumAiv());
108	    uint64_t ubSize;
109	    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
110	
111	    // ---- Block 级 Tiling (核间切分) ----
112	    // Cache Line 对齐
113	    int64_t alignElements512 = CACHE_LINE_BYTES / dtypeSize;
114	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
115	    int64_t totalLengthCoreAlign =
116	        ((totalLengthCore + alignElements512 - 1) / alignElements512) * alignElements512;
117	
118	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
119	    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
120	    if (usedCoreNum < 1) usedCoreNum = 1;
121	
122	    int64_t formerNum = usedCoreNum - 1;
123	    int64_t tailNum = 1;
124	    int64_t formerLength = totalLengthCoreAlign;
125	    int64_t tailLength = totalLength - (usedCoreNum - 1) * formerLength;
126	    if (tailLength < 0) tailLength = 0;
127	
128	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
129	
130	    // ---- UB 级 Tiling (核内切分) ----
131	    // 索引 buffer: ospat 最大约 32768, 对应 128KB
132	    // 整数对齐 indexBatchSize
133	    int64_t indexBatchSizeUnaligned = ospatSize;
134	    int64_t indexBatchBytes = indexBatchSizeUnaligned * sizeof(int32_t);
135	    // 限制索引 buffer 不超过 UB 的 60% (留 40% 给 grad data)
136	    int64_t maxIndexBytes = static_cast<int64_t>(ubSize) * 6 / 10;
137	    while (indexBatchBytes > maxIndexBytes && indexBatchSizeUnaligned > 0) {
138	        indexBatchSizeUnaligned /= 2;
139	        indexBatchBytes = indexBatchSizeUnaligned * sizeof(int32_t);
140	    }
141	    // 32B 对齐 indexBatchSize (int32: 8 elements per 32B)
142	    int64_t indexBatchSize = (indexBatchSizeUnaligned / INDEX_ALIGN_ELEMS) * INDEX_ALIGN_ELEMS;
143	    if (indexBatchSize < INDEX_ALIGN_ELEMS) indexBatchSize = INDEX_ALIGN_ELEMS;
144	
145	    // 剩余 UB 用于 grad data double buffer
146	    int64_t ubRemainingBytes = static_cast<int64_t>(ubSize) - indexBatchSize * sizeof(int32_t);
147	    int64_t maxTileElements = ubRemainingBytes / (dtypeSize * 2);  // BUFFER_NUM = 2
148	    int64_t alignElements32 = UB_ALIGN_BYTES / dtypeSize;
149	    int64_t tileLength = (maxTileElements / alignElements32) * alignElements32;
150	    if (tileLength < alignElements32) tileLength = alignElements32;
151	
152	    // ---- EXEC_KERNEL_CMD (所有参数必须为左值) ----
153	    EXEC_KERNEL_CMD(upsample_nearest_3d_grad, blockDim,
154	                    gradOutputContiguous, gradInputFlat, mappedIndicesContiguous,
155	                    totalLength, formerNum, formerLength,
156	                    tailNum, tailLength, tileLength,
157	                    ospatSize, ispatSize, indexBatchSize,
158	                    dtypeSize);
159	
160	    return gradInput;
161	}
