// ============================================================
// UpsampleNearest3dGrad — 3D 最近邻上采样反向传播
// 核心: 逐元素 scatter_add，最近邻索引在 kernel 中内联计算
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

template<typename T>
class UpsampleNearest3dGradKernel {
public:
    __aicore__ inline UpsampleNearest3dGradKernel() {}

    __aicore__ inline void Init(GM_ADDR gradOutput, GM_ADDR gradInput,
                                 int64_t totalLength, int64_t formerNum,
                                 int64_t formerLength, int64_t tailNum,
                                 int64_t tailLength, int64_t tileLength,
                                 int64_t ospatSize, int64_t ispatSize,
                                 int64_t iD, int64_t iH, int64_t iW,
                                 int64_t oD, int64_t oH, int64_t oW,
                                 float scaleD, float scaleH, float scaleW);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength);
    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength);

    TPipe pipe;

    // Double buffer for grad_output tiles
    TQue<TPosition::VECIN, BUFFER_NUM> gradQueue;
    // Single element buffer for atomic add
    TBuf<TPosition::VECOUT> atomicTempBuf;

    GlobalTensor<T> gradOutputGm;
    GlobalTensor<T> gradInputGm;

    int64_t totalLength_ = 0;
    int64_t formerNum_ = 0;
    int64_t formerLength_ = 0;
    int64_t tailNum_ = 0;
    int64_t tailLength_ = 0;
    int64_t tileLength_ = 0;
    int64_t ospatSize_ = 0;
    int64_t ispatSize_ = 0;
    int64_t iD_ = 0;
    int64_t iH_ = 0;
    int64_t iW_ = 0;
    int64_t oD_ = 0;
    int64_t oH_ = 0;
    int64_t oW_ = 0;
    float scaleD_ = 1.0f;
    float scaleH_ = 1.0f;
    float scaleW_ = 1.0f;

    // Core-local range
    int64_t coreStart_ = 0;
    int64_t coreLength_ = 0;
};

// =========================== Init ============================

template<typename T>
__aicore__ inline void UpsampleNearest3dGradKernel<T>::Init(
    GM_ADDR gradOutput, GM_ADDR gradInput,
    int64_t totalLength, int64_t formerNum, int64_t formerLength,
    int64_t tailNum, int64_t tailLength, int64_t tileLength,
    int64_t ospatSize, int64_t ispatSize,
    int64_t iD, int64_t iH, int64_t iW,
    int64_t oD, int64_t oH, int64_t oW,
    float scaleD, float scaleH, float scaleW) {

    totalLength_ = totalLength;
    formerNum_ = formerNum;
    formerLength_ = formerLength;
    tailNum_ = tailNum;
    tailLength_ = tailLength;
    tileLength_ = tileLength;
    ospatSize_ = ospatSize;
    ispatSize_ = ispatSize;
    iD_ = iD; iH_ = iH; iW_ = iW;
    oD_ = oD; oH_ = oH; oW_ = oW;
    scaleD_ = scaleD; scaleH_ = scaleH; scaleW_ = scaleW;

    gradOutputGm.SetGlobalBuffer((__gm__ T*)gradOutput);
    gradInputGm.SetGlobalBuffer((__gm__ T*)gradInput);

    // Allocate UB buffers (conservative: atomicTempBuf included in host tile calculation)
    pipe.InitBuffer(gradQueue, BUFFER_NUM, tileLength_ * sizeof(T));
    pipe.InitBuffer(atomicTempBuf, sizeof(T));

    // Determine core's range
    int64_t blockIdx = GetBlockIdx();
    if (blockIdx < formerNum_) {
        coreStart_ = blockIdx * formerLength_;
        coreLength_ = formerLength_;
    } else {
        int64_t tailIdx = blockIdx - formerNum_;
        coreStart_ = formerNum_ * formerLength_ + tailIdx * tailLength_;
        coreLength_ = (tailIdx < tailNum_ - 1) ? tailLength_
                      : (totalLength_ - coreStart_);
    }
    if (coreLength_ <= 0) coreLength_ = 0;
}

// =========================== Process ============================

template<typename T>
__aicore__ inline void UpsampleNearest3dGradKernel<T>::Process() {
    if (coreLength_ <= 0) return;

    int64_t tileNum = (coreLength_ + tileLength_ - 1) / tileLength_;
    int64_t tailTileLength = coreLength_ - (tileNum - 1) * tileLength_;

    for (int64_t i = 0; i < tileNum; ++i) {
        int64_t curTileLength = (i == tileNum - 1) ? tailTileLength : tileLength_;
        CopyIn(i, curTileLength);
        Compute(i, curTileLength);
    }
}

// =========================== CopyIn ============================

template<typename T>
__aicore__ inline void UpsampleNearest3dGradKernel<T>::CopyIn(
    int64_t progress, int64_t curTileLength) {

    int64_t globalOffset = coreStart_ + progress * tileLength_;
    LocalTensor<T> gradLocal = gradQueue.AllocTensor<T>();

    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(curTileLength * sizeof(T));
    DataCopyPadExtParams<T> padParams;
    padParams.isPad = false;
    DataCopyPad(gradLocal, gradOutputGm[globalOffset], copyParams, padParams);

    gradQueue.EnQue(gradLocal);
}

// =========================== Compute ============================

template<typename T>
__aicore__ inline void UpsampleNearest3dGradKernel<T>::Compute(
    int64_t progress, int64_t curTileLength) {

    LocalTensor<T> gradLocal = gradQueue.DeQue<T>();
    LocalTensor<T> atomicLocal = atomicTempBuf.Get<T>();

    int64_t oHW = oH_ * oW_;
    int64_t iHW = iH_ * iW_;

    int64_t globalStart = coreStart_ + progress * tileLength_;
    int64_t batchIdx = globalStart / ospatSize_;
    int64_t ospat = globalStart - batchIdx * ospatSize_;

    for (int64_t i = 0; i < curTileLength; ++i) {
        // Decompose ospat into (od, oh, ow)
        int64_t od = ospat / oHW;
        int64_t ohw = ospat - od * oHW;
        int64_t oh = ohw / oW_;
        int64_t ow = ohw - oh * oW_;

        // Nearest-neighbor source coordinates
        int64_t id = (int64_t)((float)od * scaleD_);
        if (id < 0) id = 0;
        if (id >= iD_) id = iD_ - 1;

        int64_t ih = (int64_t)((float)oh * scaleH_);
        if (ih < 0) ih = 0;
        if (ih >= iH_) ih = iH_ - 1;

        int64_t iw = (int64_t)((float)ow * scaleW_);
        if (iw < 0) iw = 0;
        if (iw >= iW_) iw = iW_ - 1;

        int64_t targetSpat = id * iHW + ih * iW_ + iw;
        int64_t targetGlobal = batchIdx * ispatSize_ + targetSpat;

        T val = gradLocal.GetValue(i);
        atomicLocal.SetValue(0, val);
        SetAtomicAdd<T>();
        DataCopyExtParams copyParams;
        copyParams.blockCount = 1;
        copyParams.blockLen = static_cast<uint32_t>(sizeof(T));
        DataCopyPad(gradInputGm[targetGlobal], atomicLocal, copyParams);
        SetAtomicNone();

        ospat++;
        if (ospat == ospatSize_) {
            ospat = 0;
            batchIdx++;
        }
    }

    gradQueue.FreeTensor(gradLocal);
}

// =========================== Kernel Entry ============================
// fp16 和 bf16 均为 2 字节搬运类操作，统一走 half 路径

extern "C" __global__ __aicore__ void upsample_nearest_3d_grad(
    GM_ADDR gradOutput, GM_ADDR gradInput,
    int64_t totalLength, int64_t formerNum, int64_t formerLength,
    int64_t tailNum, int64_t tailLength, int64_t tileLength,
    int64_t ospatSize, int64_t ispatSize,
    int64_t iD, int64_t iH, int64_t iW,
    int64_t oD, int64_t oH, int64_t oW,
    float scaleD, float scaleH, float scaleW,
    int64_t dtypeSize) {

    if (dtypeSize == 4) {
        UpsampleNearest3dGradKernel<float> op;
        op.Init(gradOutput, gradInput,
                totalLength, formerNum, formerLength,
                tailNum, tailLength, tileLength,
                ospatSize, ispatSize,
                iD, iH, iW, oD, oH, oW,
                scaleD, scaleH, scaleW);
        op.Process();
    } else if (dtypeSize == 2) {
        UpsampleNearest3dGradKernel<half> op;
        op.Init(gradOutput, gradInput,
                totalLength, formerNum, formerLength,
                tailNum, tailLength, tileLength,
                ospatSize, ispatSize,
                iD, iH, iW, oD, oH, oW,
                scaleD, scaleH, scaleW);
        op.Process();
    }
}
