// ============================================================
// UpsampleNearest3dGrad Host — Tiling + Kernel Launch
// 最近邻索引由 kernel 内联计算，不依赖预计算映射表
// ============================================================

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_upsample_nearest_3d_grad.h"
#include <torch/extension.h>
#include <algorithm>

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTES = 512;
constexpr int64_t UB_ALIGN_BYTES = 32;
constexpr int64_t UB_SAFETY_MARGIN = 512;  // 512 字节安全余量

at::Tensor upsample_nearest_3d_grad(
    const at::Tensor& grad_output,
    const at::IntArrayRef& output_size,
    const at::IntArrayRef& input_size,
    double scales_d,
    double scales_h,
    double scales_w) {

    // ---- 输入校验 ----
    TORCH_CHECK(grad_output.device().type() == at::DeviceType::PrivateUse1,
                "upsample_nearest_3d_grad: grad_output must be on NPU device");
    TORCH_CHECK(grad_output.dim() == 5,
                "upsample_nearest_3d_grad: grad_output must be 5D (N,C,D,H,W)");
    TORCH_CHECK(grad_output.scalar_type() == at::kFloat ||
                grad_output.scalar_type() == at::kHalf ||
                grad_output.scalar_type() == at::kBFloat16,
                "upsample_nearest_3d_grad: only float32, float16 and bfloat16 are supported");

    // ---- 参数提取 ----
    int64_t N = output_size[0];
    int64_t C = output_size[1];
    int64_t oD = output_size[2];
    int64_t oH = output_size[3];
    int64_t oW = output_size[4];
    int64_t iD = input_size[2];
    int64_t iH = input_size[3];
    int64_t iW = input_size[4];

    int64_t ospatSize = oD * oH * oW;
    int64_t ispatSize = iD * iH * iW;
    int64_t totalLength = N * C * ospatSize;

    int64_t dtypeSize = grad_output.element_size();

    // ---- 连续化 ----
    auto gradOutputContiguous = grad_output.contiguous();

    // ---- 创建输出 tensor ----
    auto gradInput = at::zeros({N, C, iD, iH, iW},
        grad_output.options());
    auto gradInputContiguous = gradInput.contiguous();
    auto gradInputFlat = gradInputContiguous.view({-1});

    // ---- Platform Setup ----
    auto platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(platform->GetCoreNumAiv());
    uint64_t ubSize;
    platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // ---- Block 级 Tiling (核间切分) ----
    int64_t alignElements512 = CACHE_LINE_BYTES / dtypeSize;
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign =
        ((totalLengthCore + alignElements512 - 1) / alignElements512) * alignElements512;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    if (usedCoreNum > coreNum) usedCoreNum = coreNum;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int64_t formerNum = usedCoreNum - 1;
    int64_t tailNum = 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - (usedCoreNum - 1) * formerLength;
    if (tailLength < 0) tailLength = 0;

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // ---- UB 级 Tiling (核内切分) ----
    // UB 分配: gradQueue (BUFFER_NUM=2 * tileLength * sizeof(T)) + atomicTempBuf (sizeof(T))
    // 减去安全余量
    int64_t ubAvailable = static_cast<int64_t>(ubSize) - UB_SAFETY_MARGIN;
